-- DIAGNÓSTICO (SOMENTE LEITURA) — CPF/CNPJ inválido na BASE ANTIGA (D1 "contatos"), parte 2 de 2.
-- Pedido de 21/11/2026 (Item 2, decisão 2b do Marcio: não mexer; rodar de novo de tempos em tempos,
-- a primeira vez em fevereiro de 2027).
--
-- COMO RODAR DE NOVO
--   Parte 1 (fichas, OS e pedidos do sistema novo, no KV): no GitHub, Actions → "Portal — Diagnóstico de
--   ficha com CPF/CNPJ inválido (somente leitura)" → Run workflow, no ramo
--   claude/ecobraz-carbon-tracking-system-dh28dx (script: diagnostico-ficha-documento.mjs).
--   Parte 2 (este arquivo, base antiga no D1): a chave do GitHub NÃO lê o D1 (HTTP 403); rode as três
--   consultas abaixo pela ferramenta de consulta do D1 (só SELECT), no banco DB_PLOOMES
--   (acd75607-389c-42c3-b50b-24f607350dd9). Elas devolvem só contagens e ids — nenhum nome, documento
--   ou e-mail.
--
-- REGRA de "documento inválido" (a mesma do sistema, publicação 370, conferida em 20.000 documentos
-- inventados sem divergência): dígito verificador que não confere, todos os dígitos iguais, ou tamanho
-- que não é de CPF (11) nem de CNPJ (14). Pontos, traços, barras e espaços são ignorados.
--
-- RESULTADO DE 21/11/2026 (para comparar): 27.209 contatos — PJ válidos 7.227, PF válidos 3.161,
-- PF sem documento 16.816, inválidos 5 (4 PJ com dígito verificador errado — 18075229, 18075276,
-- 18075307, 18075313 —, 1 PF com 10 dígitos — 900000005); nenhum documento inválido repetido em outro
-- contato; os 5 sem OS, pedido, negócio antigo, arquivo nem e-mail. Parte 1: 4.810 fichas (1 inválida),
-- 455 OS (0 inválidas), 169 pedidos (0 inválidos), 0 fichas com OS/pedido de documento inválido.

-- 1) Quantos contatos por situação do documento e tipo
WITH n AS (SELECT ploomes_id, tipo, LOWER(TRIM(COALESCE(nome,''))) AS nm, COALESCE(email,'') AS em, REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(documento,''),'.',''),'-',''),'/',''),' ','') AS d FROM contatos), c AS (SELECT n.*, CASE WHEN d='' THEN 'vazio'
 WHEN d GLOB '*[^0-9]*' THEN 'tamanho'
 WHEN length(d)=11 THEN CASE WHEN REPLACE(d,substr(d,1,1),'')='' THEN 'repetido' WHEN (CASE WHEN ((CAST(substr(d,1,1) AS INTEGER)*10 + CAST(substr(d,2,1) AS INTEGER)*9 + CAST(substr(d,3,1) AS INTEGER)*8 + CAST(substr(d,4,1) AS INTEGER)*7 + CAST(substr(d,5,1) AS INTEGER)*6 + CAST(substr(d,6,1) AS INTEGER)*5 + CAST(substr(d,7,1) AS INTEGER)*4 + CAST(substr(d,8,1) AS INTEGER)*3 + CAST(substr(d,9,1) AS INTEGER)*2)*10)%11=10 THEN 0 ELSE ((CAST(substr(d,1,1) AS INTEGER)*10 + CAST(substr(d,2,1) AS INTEGER)*9 + CAST(substr(d,3,1) AS INTEGER)*8 + CAST(substr(d,4,1) AS INTEGER)*7 + CAST(substr(d,5,1) AS INTEGER)*6 + CAST(substr(d,6,1) AS INTEGER)*5 + CAST(substr(d,7,1) AS INTEGER)*4 + CAST(substr(d,8,1) AS INTEGER)*3 + CAST(substr(d,9,1) AS INTEGER)*2)*10)%11 END) = CAST(substr(d,10,1) AS INTEGER) AND (CASE WHEN ((CAST(substr(d,1,1) AS INTEGER)*11 + CAST(substr(d,2,1) AS INTEGER)*10 + CAST(substr(d,3,1) AS INTEGER)*9 + CAST(substr(d,4,1) AS INTEGER)*8 + CAST(substr(d,5,1) AS INTEGER)*7 + CAST(substr(d,6,1) AS INTEGER)*6 + CAST(substr(d,7,1) AS INTEGER)*5 + CAST(substr(d,8,1) AS INTEGER)*4 + CAST(substr(d,9,1) AS INTEGER)*3 + CAST(substr(d,10,1) AS INTEGER)*2)*10)%11=10 THEN 0 ELSE ((CAST(substr(d,1,1) AS INTEGER)*11 + CAST(substr(d,2,1) AS INTEGER)*10 + CAST(substr(d,3,1) AS INTEGER)*9 + CAST(substr(d,4,1) AS INTEGER)*8 + CAST(substr(d,5,1) AS INTEGER)*7 + CAST(substr(d,6,1) AS INTEGER)*6 + CAST(substr(d,7,1) AS INTEGER)*5 + CAST(substr(d,8,1) AS INTEGER)*4 + CAST(substr(d,9,1) AS INTEGER)*3 + CAST(substr(d,10,1) AS INTEGER)*2)*10)%11 END) = CAST(substr(d,11,1) AS INTEGER) THEN 'ok' ELSE 'dv' END
 WHEN length(d)=14 THEN CASE WHEN REPLACE(d,substr(d,1,1),'')='' THEN 'repetido' WHEN (CASE WHEN (CAST(substr(d,1,1) AS INTEGER)*5 + CAST(substr(d,2,1) AS INTEGER)*4 + CAST(substr(d,3,1) AS INTEGER)*3 + CAST(substr(d,4,1) AS INTEGER)*2 + CAST(substr(d,5,1) AS INTEGER)*9 + CAST(substr(d,6,1) AS INTEGER)*8 + CAST(substr(d,7,1) AS INTEGER)*7 + CAST(substr(d,8,1) AS INTEGER)*6 + CAST(substr(d,9,1) AS INTEGER)*5 + CAST(substr(d,10,1) AS INTEGER)*4 + CAST(substr(d,11,1) AS INTEGER)*3 + CAST(substr(d,12,1) AS INTEGER)*2)%11<2 THEN 0 ELSE 11-(CAST(substr(d,1,1) AS INTEGER)*5 + CAST(substr(d,2,1) AS INTEGER)*4 + CAST(substr(d,3,1) AS INTEGER)*3 + CAST(substr(d,4,1) AS INTEGER)*2 + CAST(substr(d,5,1) AS INTEGER)*9 + CAST(substr(d,6,1) AS INTEGER)*8 + CAST(substr(d,7,1) AS INTEGER)*7 + CAST(substr(d,8,1) AS INTEGER)*6 + CAST(substr(d,9,1) AS INTEGER)*5 + CAST(substr(d,10,1) AS INTEGER)*4 + CAST(substr(d,11,1) AS INTEGER)*3 + CAST(substr(d,12,1) AS INTEGER)*2)%11 END) = CAST(substr(d,13,1) AS INTEGER) AND (CASE WHEN (CAST(substr(d,1,1) AS INTEGER)*6 + CAST(substr(d,2,1) AS INTEGER)*5 + CAST(substr(d,3,1) AS INTEGER)*4 + CAST(substr(d,4,1) AS INTEGER)*3 + CAST(substr(d,5,1) AS INTEGER)*2 + CAST(substr(d,6,1) AS INTEGER)*9 + CAST(substr(d,7,1) AS INTEGER)*8 + CAST(substr(d,8,1) AS INTEGER)*7 + CAST(substr(d,9,1) AS INTEGER)*6 + CAST(substr(d,10,1) AS INTEGER)*5 + CAST(substr(d,11,1) AS INTEGER)*4 + CAST(substr(d,12,1) AS INTEGER)*3 + CAST(substr(d,13,1) AS INTEGER)*2)%11<2 THEN 0 ELSE 11-(CAST(substr(d,1,1) AS INTEGER)*6 + CAST(substr(d,2,1) AS INTEGER)*5 + CAST(substr(d,3,1) AS INTEGER)*4 + CAST(substr(d,4,1) AS INTEGER)*3 + CAST(substr(d,5,1) AS INTEGER)*2 + CAST(substr(d,6,1) AS INTEGER)*9 + CAST(substr(d,7,1) AS INTEGER)*8 + CAST(substr(d,8,1) AS INTEGER)*7 + CAST(substr(d,9,1) AS INTEGER)*6 + CAST(substr(d,10,1) AS INTEGER)*5 + CAST(substr(d,11,1) AS INTEGER)*4 + CAST(substr(d,12,1) AS INTEGER)*3 + CAST(substr(d,13,1) AS INTEGER)*2)%11 END) = CAST(substr(d,14,1) AS INTEGER) THEN 'ok' ELSE 'dv' END
 ELSE 'tamanho' END AS sit FROM n) SELECT sit, tipo, COUNT(*) AS n FROM c GROUP BY sit, tipo ORDER BY sit, tipo;

-- 2) Cada contato com documento inválido: só id, tipo, motivo e contagens (outros com o mesmo documento,
--    nomes distintos no documento, se tem e-mail, pessoas vinculadas, negócios, origem)
WITH n AS (SELECT ploomes_id, tipo, LOWER(TRIM(COALESCE(nome,''))) AS nm, COALESCE(email,'') AS em, REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(documento,''),'.',''),'-',''),'/',''),' ','') AS d FROM contatos), c AS (SELECT n.*, CASE WHEN d='' THEN 'vazio'
 WHEN d GLOB '*[^0-9]*' THEN 'tamanho'
 WHEN length(d)=11 THEN CASE WHEN REPLACE(d,substr(d,1,1),'')='' THEN 'repetido' WHEN (CASE WHEN ((CAST(substr(d,1,1) AS INTEGER)*10 + CAST(substr(d,2,1) AS INTEGER)*9 + CAST(substr(d,3,1) AS INTEGER)*8 + CAST(substr(d,4,1) AS INTEGER)*7 + CAST(substr(d,5,1) AS INTEGER)*6 + CAST(substr(d,6,1) AS INTEGER)*5 + CAST(substr(d,7,1) AS INTEGER)*4 + CAST(substr(d,8,1) AS INTEGER)*3 + CAST(substr(d,9,1) AS INTEGER)*2)*10)%11=10 THEN 0 ELSE ((CAST(substr(d,1,1) AS INTEGER)*10 + CAST(substr(d,2,1) AS INTEGER)*9 + CAST(substr(d,3,1) AS INTEGER)*8 + CAST(substr(d,4,1) AS INTEGER)*7 + CAST(substr(d,5,1) AS INTEGER)*6 + CAST(substr(d,6,1) AS INTEGER)*5 + CAST(substr(d,7,1) AS INTEGER)*4 + CAST(substr(d,8,1) AS INTEGER)*3 + CAST(substr(d,9,1) AS INTEGER)*2)*10)%11 END) = CAST(substr(d,10,1) AS INTEGER) AND (CASE WHEN ((CAST(substr(d,1,1) AS INTEGER)*11 + CAST(substr(d,2,1) AS INTEGER)*10 + CAST(substr(d,3,1) AS INTEGER)*9 + CAST(substr(d,4,1) AS INTEGER)*8 + CAST(substr(d,5,1) AS INTEGER)*7 + CAST(substr(d,6,1) AS INTEGER)*6 + CAST(substr(d,7,1) AS INTEGER)*5 + CAST(substr(d,8,1) AS INTEGER)*4 + CAST(substr(d,9,1) AS INTEGER)*3 + CAST(substr(d,10,1) AS INTEGER)*2)*10)%11=10 THEN 0 ELSE ((CAST(substr(d,1,1) AS INTEGER)*11 + CAST(substr(d,2,1) AS INTEGER)*10 + CAST(substr(d,3,1) AS INTEGER)*9 + CAST(substr(d,4,1) AS INTEGER)*8 + CAST(substr(d,5,1) AS INTEGER)*7 + CAST(substr(d,6,1) AS INTEGER)*6 + CAST(substr(d,7,1) AS INTEGER)*5 + CAST(substr(d,8,1) AS INTEGER)*4 + CAST(substr(d,9,1) AS INTEGER)*3 + CAST(substr(d,10,1) AS INTEGER)*2)*10)%11 END) = CAST(substr(d,11,1) AS INTEGER) THEN 'ok' ELSE 'dv' END
 WHEN length(d)=14 THEN CASE WHEN REPLACE(d,substr(d,1,1),'')='' THEN 'repetido' WHEN (CASE WHEN (CAST(substr(d,1,1) AS INTEGER)*5 + CAST(substr(d,2,1) AS INTEGER)*4 + CAST(substr(d,3,1) AS INTEGER)*3 + CAST(substr(d,4,1) AS INTEGER)*2 + CAST(substr(d,5,1) AS INTEGER)*9 + CAST(substr(d,6,1) AS INTEGER)*8 + CAST(substr(d,7,1) AS INTEGER)*7 + CAST(substr(d,8,1) AS INTEGER)*6 + CAST(substr(d,9,1) AS INTEGER)*5 + CAST(substr(d,10,1) AS INTEGER)*4 + CAST(substr(d,11,1) AS INTEGER)*3 + CAST(substr(d,12,1) AS INTEGER)*2)%11<2 THEN 0 ELSE 11-(CAST(substr(d,1,1) AS INTEGER)*5 + CAST(substr(d,2,1) AS INTEGER)*4 + CAST(substr(d,3,1) AS INTEGER)*3 + CAST(substr(d,4,1) AS INTEGER)*2 + CAST(substr(d,5,1) AS INTEGER)*9 + CAST(substr(d,6,1) AS INTEGER)*8 + CAST(substr(d,7,1) AS INTEGER)*7 + CAST(substr(d,8,1) AS INTEGER)*6 + CAST(substr(d,9,1) AS INTEGER)*5 + CAST(substr(d,10,1) AS INTEGER)*4 + CAST(substr(d,11,1) AS INTEGER)*3 + CAST(substr(d,12,1) AS INTEGER)*2)%11 END) = CAST(substr(d,13,1) AS INTEGER) AND (CASE WHEN (CAST(substr(d,1,1) AS INTEGER)*6 + CAST(substr(d,2,1) AS INTEGER)*5 + CAST(substr(d,3,1) AS INTEGER)*4 + CAST(substr(d,4,1) AS INTEGER)*3 + CAST(substr(d,5,1) AS INTEGER)*2 + CAST(substr(d,6,1) AS INTEGER)*9 + CAST(substr(d,7,1) AS INTEGER)*8 + CAST(substr(d,8,1) AS INTEGER)*7 + CAST(substr(d,9,1) AS INTEGER)*6 + CAST(substr(d,10,1) AS INTEGER)*5 + CAST(substr(d,11,1) AS INTEGER)*4 + CAST(substr(d,12,1) AS INTEGER)*3 + CAST(substr(d,13,1) AS INTEGER)*2)%11<2 THEN 0 ELSE 11-(CAST(substr(d,1,1) AS INTEGER)*6 + CAST(substr(d,2,1) AS INTEGER)*5 + CAST(substr(d,3,1) AS INTEGER)*4 + CAST(substr(d,4,1) AS INTEGER)*3 + CAST(substr(d,5,1) AS INTEGER)*2 + CAST(substr(d,6,1) AS INTEGER)*9 + CAST(substr(d,7,1) AS INTEGER)*8 + CAST(substr(d,8,1) AS INTEGER)*7 + CAST(substr(d,9,1) AS INTEGER)*6 + CAST(substr(d,10,1) AS INTEGER)*5 + CAST(substr(d,11,1) AS INTEGER)*4 + CAST(substr(d,12,1) AS INTEGER)*3 + CAST(substr(d,13,1) AS INTEGER)*2)%11 END) = CAST(substr(d,14,1) AS INTEGER) THEN 'ok' ELSE 'dv' END
 ELSE 'tamanho' END AS sit FROM n) , inv AS (SELECT * FROM c WHERE sit IN ('dv','repetido','tamanho'))
SELECT inv.ploomes_id, inv.tipo, inv.sit, length(inv.d) AS tamanho,
  (SELECT COUNT(*) FROM c x WHERE x.d = inv.d AND x.ploomes_id <> inv.ploomes_id) AS outros_com_mesmo_doc,
  (SELECT COUNT(DISTINCT x.nm) FROM c x WHERE x.d = inv.d) AS nomes_distintos_no_doc,
  CASE WHEN inv.em <> '' THEN 1 ELSE 0 END AS tem_email,
  (SELECT COUNT(*) FROM contatos p WHERE p.company_id = inv.ploomes_id) AS pessoas_vinculadas,
  (SELECT COUNT(*) FROM negocios g WHERE g.contact_id = inv.ploomes_id) AS negocios,
  CASE WHEN inv.ploomes_id >= 900000000 THEN 'criado pelo sistema novo' ELSE 'veio do Ploomes' END AS origem
FROM inv ORDER BY inv.ploomes_id;

-- 3) Para os ids da consulta 2: arquivos, pessoas vinculadas com e-mail e negócios delas (troque o 0
--    pela lista de ids)
SELECT c.ploomes_id, (SELECT COUNT(*) FROM arquivos_ploomes a WHERE a.contact_id = c.ploomes_id) AS arquivos, (SELECT COUNT(*) FROM contatos p WHERE p.company_id = c.ploomes_id AND COALESCE(p.email,'') <> '') AS pessoas_com_email, (SELECT COUNT(*) FROM negocios g WHERE g.person_id IN (SELECT ploomes_id FROM contatos p2 WHERE p2.company_id = c.ploomes_id)) AS negocios_das_pessoas FROM contatos c WHERE c.ploomes_id IN (/* ids da consulta 2 */ 0) ORDER BY c.ploomes_id;
